export const DEPENDENT_DROPDOWN_SERVICE = "import { Injectable } from '@angular/core';\nimport { Observable, of, delay } from 'rxjs';\n\nexport interface GeoOption {\n  code: string;\n  name: string;\n}\n\nconst GEO_DATA: Record<string, { states: GeoOption[] }> = {\n  IND: {\n    states: [\n      { code: 'MH', name: 'Maharashtra' },\n      { code: 'KA', name: 'Karnataka' },\n      { code: 'TN', name: 'Tamil Nadu' },\n      { code: 'DL', name: 'Delhi' },\n    ],\n  },\n  USA: {\n    states: [\n      { code: 'CA', name: 'California' },\n      { code: 'NY', name: 'New York' },\n      { code: 'TX', name: 'Texas' },\n      { code: 'FL', name: 'Florida' },\n    ],\n  },\n  GBR: {\n    states: [\n      { code: 'ENG', name: 'England' },\n      { code: 'SCT', name: 'Scotland' },\n      { code: 'WLS', name: 'Wales' },\n    ],\n  },\n  SGP: {\n    states: [\n      { code: 'CTL', name: 'Central Region' },\n      { code: 'EST', name: 'East Region' },\n      { code: 'WST', name: 'West Region' },\n    ],\n  },\n};\n\nconst CITY_DATA: Record<string, GeoOption[]> = {\n  MH: [\n    { code: 'MUM', name: 'Mumbai' },\n    { code: 'PUN', name: 'Pune' },\n    { code: 'NGP', name: 'Nagpur' },\n  ],\n  KA: [\n    { code: 'BLR', name: 'Bengaluru' },\n    { code: 'MYS', name: 'Mysuru' },\n    { code: 'HBL', name: 'Hubballi' },\n  ],\n  TN: [\n    { code: 'CHE', name: 'Chennai' },\n    { code: 'CBE', name: 'Coimbatore' },\n    { code: 'MDU', name: 'Madurai' },\n  ],\n  DL: [\n    { code: 'NDL', name: 'New Delhi' },\n    { code: 'NDA', name: 'Noida' },\n    { code: 'GRG', name: 'Gurugram' },\n  ],\n  CA: [\n    { code: 'LAX', name: 'Los Angeles' },\n    { code: 'SFO', name: 'San Francisco' },\n    { code: 'SDO', name: 'San Diego' },\n  ],\n  NY: [\n    { code: 'NYC', name: 'New York City' },\n    { code: 'BUF', name: 'Buffalo' },\n    { code: 'ALB', name: 'Albany' },\n  ],\n  TX: [\n    { code: 'HOU', name: 'Houston' },\n    { code: 'DAL', name: 'Dallas' },\n    { code: 'AUS', name: 'Austin' },\n  ],\n  FL: [\n    { code: 'MIA', name: 'Miami' },\n    { code: 'ORL', name: 'Orlando' },\n    { code: 'TPA', name: 'Tampa' },\n  ],\n  ENG: [\n    { code: 'LON', name: 'London' },\n    { code: 'MAN', name: 'Manchester' },\n    { code: 'BRM', name: 'Birmingham' },\n  ],\n  SCT: [\n    { code: 'EDI', name: 'Edinburgh' },\n    { code: 'GLA', name: 'Glasgow' },\n  ],\n  WLS: [\n    { code: 'CDF', name: 'Cardiff' },\n    { code: 'SWA', name: 'Swansea' },\n  ],\n  CTL: [\n    { code: 'ORH', name: 'Orchard' },\n    { code: 'MAR', name: 'Marina Bay' },\n  ],\n  EST: [\n    { code: 'TAM', name: 'Tampines' },\n    { code: 'BED', name: 'Bedok' },\n  ],\n  WST: [\n    { code: 'JRG', name: 'Jurong' },\n    { code: 'CLM', name: 'Clementi' },\n  ],\n};\n\n/**\n * GeoService â€” Simulates async HTTP calls for geographic data.\n * Uses RxJS `of()` + `delay()` to mimic real API latency.\n *\n * In a real Fintech app, these would be:\n *   GET /api/v1/geo/countries\n *   GET /api/v1/geo/states?country={code}\n *   GET /api/v1/geo/cities?state={code}\n */\n@Injectable({ providedIn: 'root' })\nexport class GeoService {\n  readonly countries: GeoOption[] = [\n    { code: 'IND', name: 'India' },\n    { code: 'USA', name: 'United States' },\n    { code: 'GBR', name: 'United Kingdom' },\n    { code: 'SGP', name: 'Singapore' },\n  ];\n\n  getStates(countryCode: string): Observable<GeoOption[]> {\n    const states = GEO_DATA[countryCode]?.states ?? [];\n    return of(states).pipe(delay(600)); // simulate network latency\n  }\n\n  getCities(stateCode: string): Observable<GeoOption[]> {\n    const cities = CITY_DATA[stateCode] ?? [];\n    return of(cities).pipe(delay(500));\n  }\n}\n";

export const DEBOUNCE_DEMO_TS = "import {\n  Component,\n  OnInit,\n  OnDestroy,\n  ElementRef,\n  ViewChild,\n} from '@angular/core';\nimport { CommonModule } from '@angular/common';\nimport { FormsModule } from '@angular/forms';\nimport {\n  Subject,\n  fromEvent,\n  debounceTime,\n  distinctUntilChanged,\n  switchMap,\n  takeUntil,\n  of,\n} from 'rxjs';\nimport {\n  CustomerSearchService,\n  CustomerResult,\n} from './customer-search.service';\nimport { CodeViewerComponent, CodeFile } from '../code-viewer/code-viewer.component';\nimport {\n  DEBOUNCE_DEMO_TS,\n  DEBOUNCE_DEMO_HTML,\n  DEBOUNCE_DEMO_SERVICE,\n} from '../code-snippets';\n\ninterface CallEvent {\n  timestamp: string;\n  query: string;\n  type: 'naive' | 'debounced';\n  hit: boolean; // true = actual API hit\n}\n\n/**\n * DebounceDemoComponent\n *\n * Demonstrates WHY debouncing is essential in Fintech search UIs.\n *\n * Problem: Without debounce, every keystroke fires an API call.\n *   User types \"Arjun\" = 5 keystrokes = 5 API calls.\n *   Only the LAST one matters. The other 4 are wasted compute + network.\n *\n * Solution: debounceTime(400) â€” waits 400ms after the LAST keystroke.\n *   User types \"Arjun\" quickly = only 1 API call, fired after 400ms silence.\n *\n * Combined with:\n *   - distinctUntilChanged() â†’ skips API call if value didn't actually change\n *   - switchMap() â†’ cancels in-flight requests when a new search arrives\n *   - takeUntil(destroy$) â†’ cleans up subscriptions on component destroy\n */\n@Component({\n  selector: 'lib-debounce-demo',\n  standalone: true,\n  imports: [CommonModule, FormsModule, CodeViewerComponent],\n  templateUrl: './debounce-demo.component.html',\n  styleUrls: ['./debounce-demo.component.scss'],\n})\nexport class DebounceDemoComponent implements OnInit, OnDestroy {\n  @ViewChild('naiveInput', { static: true }) naiveInputRef!: ElementRef<HTMLInputElement>;\n  @ViewChild('debouncedInput', { static: true }) debouncedInputRef!: ElementRef<HTMLInputElement>;\n\n  readonly codeFiles: CodeFile[] = [\n    {\n      name: 'debounce-demo.component.ts',\n      code: DEBOUNCE_DEMO_TS,\n      language: 'typescript',\n    },\n    {\n      name: 'debounce-demo.component.html',\n      code: DEBOUNCE_DEMO_HTML,\n      language: 'html',\n    },\n    {\n      name: 'customer-search.service.ts',\n      code: DEBOUNCE_DEMO_SERVICE,\n      language: 'typescript',\n    },\n  ];\n\n  naiveQuery = '';\n  debouncedQuery = '';\n\n  naiveResults: CustomerResult[] = [];\n  debouncedResults: CustomerResult[] = [];\n\n  naiveCallCount = 0;\n  debouncedCallCount = 0;\n  callsSaved = 0;\n\n  naiveLoading = false;\n  debouncedLoading = false;\n\n  callLog: CallEvent[] = [];\n  private keystrokeCount = 0;\n\n  private destroy$ = new Subject<void>();\n\n  constructor(private searchService: CustomerSearchService) {}\n\n  ngOnInit(): void {\n    this.searchService.resetCallCount();\n    this.wireNaiveInput();\n    this.wireDebouncedInput();\n  }\n\n  /**\n   * NAIVE APPROACH â€” no debounce\n   * Every keyup event fires a search immediately.\n   * This is the BAD pattern. Watch the call counter skyrocket.\n   */\n  private wireNaiveInput(): void {\n    fromEvent<Event>(this.naiveInputRef.nativeElement, 'input')\n      .pipe(takeUntil(this.destroy$))\n      .subscribe((event) => {\n        const query = (event.target as HTMLInputElement).value;\n        this.keystrokeCount++;\n        this.callsSaved = Math.max(0, this.keystrokeCount - this.debouncedCallCount);\n\n        if (!query.trim()) {\n          this.naiveResults = [];\n          this.naiveLoading = false;\n          return;\n        }\n\n        this.naiveLoading = true;\n        this.naiveCallCount++;\n        this.logCall(query, 'naive', true);\n\n        this.searchService.search(query).pipe(takeUntil(this.destroy$)).subscribe({\n          next: (results) => {\n            this.naiveResults = results;\n            this.naiveLoading = false;\n          },\n        });\n      });\n  }\n\n  /**\n   * DEBOUNCED APPROACH â€” the correct pattern\n   *\n   * Operator pipeline:\n   *  1. debounceTime(400) â€” waits 400ms after last keystroke before emitting\n   *  2. distinctUntilChanged() â€” skips if value is the same as previous emit\n   *  3. switchMap() â€” cancels the previous observable if a new value arrives;\n   *                   prevents race conditions with out-of-order API responses\n   */\n  private wireDebouncedInput(): void {\n    fromEvent<Event>(this.debouncedInputRef.nativeElement, 'input')\n      .pipe(\n        debounceTime(400),         // â† KEY: wait 400ms of silence\n        distinctUntilChanged(),    // â† skip if value is unchanged\n        switchMap((event) => {     // â† cancel previous, start new\n          const query = (event.target as HTMLInputElement).value;\n          this.logCall(query, 'debounced', !!query.trim());\n\n          if (!query.trim()) {\n            this.debouncedResults = [];\n            this.debouncedLoading = false;\n            return of([]);\n          }\n\n          this.debouncedLoading = true;\n          this.debouncedCallCount++;\n          this.callsSaved = Math.max(0, this.keystrokeCount - this.debouncedCallCount);\n\n          return this.searchService.search(query);\n        }),\n        takeUntil(this.destroy$)\n      )\n      .subscribe({\n        next: (results) => {\n          this.debouncedResults = results;\n          this.debouncedLoading = false;\n        },\n      });\n  }\n\n  private logCall(query: string, type: 'naive' | 'debounced', hit: boolean): void {\n    const now = new Date();\n    const timestamp = `${now.getHours().toString().padStart(2, '0')}:${now\n      .getMinutes()\n      .toString()\n      .padStart(2, '0')}:${now.getSeconds().toString().padStart(2, '0')}.${now\n      .getMilliseconds()\n      .toString()\n      .padStart(3, '0')}`;\n\n    this.callLog.unshift({ timestamp, query, type, hit });\n    if (this.callLog.length > 20) this.callLog.pop();\n  }\n\n  onReset(): void {\n    this.naiveQuery = '';\n    this.debouncedQuery = '';\n    this.naiveResults = [];\n    this.debouncedResults = [];\n    this.naiveCallCount = 0;\n    this.debouncedCallCount = 0;\n    this.callsSaved = 0;\n    this.keystrokeCount = 0;\n    this.callLog = [];\n    this.naiveInputRef.nativeElement.value = '';\n    this.debouncedInputRef.nativeElement.value = '';\n    this.searchService.resetCallCount();\n  }\n\n  getRiskClass(risk: string): string {\n    return `risk-${risk.toLowerCase()}`;\n  }\n\n  get efficiencyPercent(): number {\n    if (this.keystrokeCount === 0) return 0;\n    return Math.round((this.callsSaved / this.keystrokeCount) * 100);\n  }\n\n  ngOnDestroy(): void {\n    this.destroy$.next();\n    this.destroy$.complete();\n  }\n}\n";

export const DEBOUNCE_DEMO_HTML = "<section class=\"demo-page\">\n  <!-- Page Header -->\n  <div class=\"demo-header\">\n    <div class=\"demo-badge\">Feature 02</div>\n    <h1 class=\"demo-title\">Debounce API Guard</h1>\n    <p class=\"demo-subtitle\">\n      Prevent rapid-fire API calls using RxJS <strong>debounceTime</strong>,\n      <strong>distinctUntilChanged</strong>, and <strong>switchMap</strong>.\n      Type in both panels and watch the API call counters in real-time.\n    </p>\n  </div>\n\n  <!-- Concept Tags -->\n  <div class=\"concept-tags\">\n    <span class=\"tag\">debounceTime(400)</span>\n    <span class=\"tag\">distinctUntilChanged()</span>\n    <span class=\"tag\">switchMap()</span>\n    <span class=\"tag\">fromEvent()</span>\n    <span class=\"tag\">takeUntil</span>\n  </div>\n\n  <!-- Debounce Explainer -->\n  <div class=\"card explainer-card\">\n    <div class=\"explainer-header\">\n      <svg class=\"explainer-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\">\n        <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M12 6v6l4 2M12 22a10 10 0 100-20 10 10 0 000 20z\"/>\n      </svg>\n      <span>What is Debouncing?</span>\n    </div>\n    <div class=\"explainer-body\">\n      <p class=\"explainer-text\">\n        <strong>Debouncing</strong> is a technique that delays the execution of a function until\n        a specified time has elapsed since it was last invoked. In the context of API calls:\n      </p>\n      <div class=\"timeline-container\">\n        <div class=\"timeline-label\">Without Debounce (Naive) â€” typing \"Arjun\":</div>\n        <div class=\"timeline-row\">\n          <div class=\"timeline-key fired\">A<br><span>API</span></div>\n          <div class=\"timeline-key fired\">r<br><span>API</span></div>\n          <div class=\"timeline-key fired\">j<br><span>API</span></div>\n          <div class=\"timeline-key fired\">u<br><span>API</span></div>\n          <div class=\"timeline-key fired\">n<br><span>API</span></div>\n        </div>\n        <div class=\"timeline-verdict bad\">5 keystrokes = 5 API calls ðŸ”´</div>\n\n        <div class=\"timeline-label\" style=\"margin-top:1rem;\">With debounceTime(400ms) â€” typing \"Arjun\":</div>\n        <div class=\"timeline-row\">\n          <div class=\"timeline-key skipped\">A<br><span>waitâ€¦</span></div>\n          <div class=\"timeline-key skipped\">r<br><span>waitâ€¦</span></div>\n          <div class=\"timeline-key skipped\">j<br><span>waitâ€¦</span></div>\n          <div class=\"timeline-key skipped\">u<br><span>waitâ€¦</span></div>\n          <div class=\"timeline-key final\">n<br><span>API âœ“</span></div>\n        </div>\n        <div class=\"timeline-verdict good\">5 keystrokes = 1 API call ðŸŸ¢ (after 400ms silence)</div>\n      </div>\n\n      <div class=\"operator-list\">\n        <div class=\"operator-item\">\n          <code class=\"op-name\">debounceTime(400)</code>\n          <span class=\"op-desc\">Emits a value only after 400ms have passed with no new emissions. Resets the timer on every new keystroke.</span>\n        </div>\n        <div class=\"operator-item\">\n          <code class=\"op-name\">distinctUntilChanged()</code>\n          <span class=\"op-desc\">Skips the API call entirely if the value hasn't changed since the last emission. Prevents duplicate requests.</span>\n        </div>\n        <div class=\"operator-item\">\n          <code class=\"op-name\">switchMap()</code>\n          <span class=\"op-desc\">Cancels the previous in-flight Observable when a new value arrives. Prevents race conditions and stale data.</span>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Live Stats Bar -->\n  <div class=\"stats-bar\">\n    <div class=\"stat-item\">\n      <div class=\"stat-value stat-value--red\">{{ naiveCallCount }}</div>\n      <div class=\"stat-label\">Naive API Calls</div>\n    </div>\n    <div class=\"stat-divider\"></div>\n    <div class=\"stat-item\">\n      <div class=\"stat-value stat-value--green\">{{ debouncedCallCount }}</div>\n      <div class=\"stat-label\">Debounced API Calls</div>\n    </div>\n    <div class=\"stat-divider\"></div>\n    <div class=\"stat-item\">\n      <div class=\"stat-value stat-value--gold\">{{ callsSaved }}</div>\n      <div class=\"stat-label\">Calls Saved</div>\n    </div>\n    <div class=\"stat-divider\"></div>\n    <div class=\"stat-item\">\n      <div class=\"stat-value stat-value--blue\">{{ efficiencyPercent }}%</div>\n      <div class=\"stat-label\">Efficiency Gain</div>\n    </div>\n    <button class=\"reset-btn\" (click)=\"onReset()\" id=\"reset-demo-btn\">Reset Demo</button>\n  </div>\n\n  <!-- Side-by-Side Panels -->\n  <div class=\"panels-grid\">\n\n    <!-- Naive Panel -->\n    <div class=\"panel panel--naive\">\n      <div class=\"panel-header\">\n        <div class=\"panel-badge panel-badge--bad\">âŒ Naive (No Debounce)</div>\n        <div class=\"panel-call-count\">{{ naiveCallCount }} calls</div>\n      </div>\n      <div class=\"panel-body\">\n        <div class=\"search-box\">\n          <svg class=\"search-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\n            <circle cx=\"11\" cy=\"11\" r=\"8\"/>\n            <path stroke-linecap=\"round\" d=\"M21 21l-4.35-4.35\"/>\n          </svg>\n          <input\n            #naiveInput\n            id=\"naive-search-input\"\n            type=\"text\"\n            class=\"search-input search-input--naive\"\n            placeholder=\"Type a customer nameâ€¦\"\n            autocomplete=\"off\"\n          />\n          <div class=\"loading-dot\" [class.loading-dot--active]=\"naiveLoading\"></div>\n        </div>\n        <div class=\"code-snippet\">\n          <pre><code>// Every keystroke fires immediately\nfromEvent(input, 'input')\n  .subscribe(query => api.search(query));\n          </code></pre>\n        </div>\n        <div class=\"results-list\" *ngIf=\"naiveResults.length > 0\">\n          <div class=\"result-item\" *ngFor=\"let customer of naiveResults\">\n            <div class=\"customer-info\">\n              <div class=\"customer-name\">{{ customer.name }}</div>\n              <div class=\"customer-meta\">{{ customer.accountNo }} Â· {{ customer.product }}</div>\n            </div>\n            <div class=\"risk-badge\" [class]=\"getRiskClass(customer.risk)\">{{ customer.risk }}</div>\n          </div>\n        </div>\n        <div class=\"empty-state\" *ngIf=\"naiveResults.length === 0 && naiveCallCount > 0 && !naiveLoading\">\n          No results found\n        </div>\n        <div class=\"empty-state\" *ngIf=\"naiveCallCount === 0\">\n          Start typing to see naive behaviorâ€¦\n        </div>\n      </div>\n    </div>\n\n    <!-- Debounced Panel -->\n    <div class=\"panel panel--debounced\">\n      <div class=\"panel-header\">\n        <div class=\"panel-badge panel-badge--good\">âœ… Debounced (400ms)</div>\n        <div class=\"panel-call-count\">{{ debouncedCallCount }} calls</div>\n      </div>\n      <div class=\"panel-body\">\n        <div class=\"search-box\">\n          <svg class=\"search-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\n            <circle cx=\"11\" cy=\"11\" r=\"8\"/>\n            <path stroke-linecap=\"round\" d=\"M21 21l-4.35-4.35\"/>\n          </svg>\n          <input\n            #debouncedInput\n            id=\"debounced-search-input\"\n            type=\"text\"\n            class=\"search-input search-input--debounced\"\n            placeholder=\"Type a customer nameâ€¦\"\n            autocomplete=\"off\"\n          />\n          <div class=\"loading-dot\" [class.loading-dot--active]=\"debouncedLoading\"></div>\n        </div>\n        <div class=\"code-snippet\">\n          <pre><code>// Only fires after 400ms silence\nfromEvent(input, 'input').pipe(\n  debounceTime(400),\n  distinctUntilChanged(),\n  switchMap(q => api.search(q))\n).subscribe(results => ...);</code></pre>\n        </div>\n        <div class=\"results-list\" *ngIf=\"debouncedResults.length > 0\">\n          <div class=\"result-item\" *ngFor=\"let customer of debouncedResults\">\n            <div class=\"customer-info\">\n              <div class=\"customer-name\">{{ customer.name }}</div>\n              <div class=\"customer-meta\">{{ customer.accountNo }} Â· {{ customer.product }}</div>\n            </div>\n            <div class=\"risk-badge\" [class]=\"getRiskClass(customer.risk)\">{{ customer.risk }}</div>\n          </div>\n        </div>\n        <div class=\"empty-state\" *ngIf=\"debouncedResults.length === 0 && debouncedCallCount > 0 && !debouncedLoading\">\n          No results found\n        </div>\n        <div class=\"empty-state\" *ngIf=\"debouncedCallCount === 0\">\n          Start typing â€” API fires only after you pauseâ€¦\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Call Log -->\n  <div class=\"card log-card\" *ngIf=\"callLog.length > 0\">\n    <div class=\"log-header\">Live API Call Log</div>\n    <div class=\"log-list\">\n      <div class=\"log-entry\" *ngFor=\"let entry of callLog\"\n        [class.log-entry--naive]=\"entry.type === 'naive'\"\n        [class.log-entry--debounced]=\"entry.type === 'debounced'\">\n        <span class=\"log-time\">{{ entry.timestamp }}</span>\n        <span class=\"log-type\">{{ entry.type === 'naive' ? 'âŒ NAIVE' : 'âœ… DEBOUNCED' }}</span>\n        <span class=\"log-query\">\"{{ entry.query }}\"</span>\n        <span class=\"log-hit\" [class.log-hit--yes]=\"entry.hit\" [class.log-hit--no]=\"!entry.hit\">\n          {{ entry.hit ? 'API HIT' : 'SKIPPED' }}\n        </span>\n      </div>\n    </div>\n  </div>\n\n  <!-- Implementation Code Viewer -->\n  <div class=\"card code-card-full\">\n    <div class=\"code-card-header\">\n      <svg class=\"code-card-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\">\n        <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M17.25 6.75L22.5 12l-5.25 5.25m-10.5 0L1.5 12l5.25-5.25m7.5-3l-4.5 16.5\" />\n      </svg>\n      <span>Implementation Source Code</span>\n    </div>\n    <div class=\"code-card-body\">\n      <lib-code-viewer [files]=\"codeFiles\"></lib-code-viewer>\n    </div>\n  </div>\n</section>\n";

export const DEBOUNCE_DEMO_SERVICE = "import { Injectable } from '@angular/core';\nimport { Observable, of, delay, tap } from 'rxjs';\n\nexport interface CustomerResult {\n  id: string;\n  name: string;\n  accountNo: string;\n  product: string;\n  risk: 'LOW' | 'MEDIUM' | 'HIGH';\n}\n\nconst MOCK_CUSTOMERS: CustomerResult[] = [\n  { id: 'C001', name: 'Arjun Mehta', accountNo: 'ACC-10023', product: 'Personal Loan', risk: 'LOW' },\n  { id: 'C002', name: 'Priya Sharma', accountNo: 'ACC-10045', product: 'Credit Card', risk: 'MEDIUM' },\n  { id: 'C003', name: 'Rahul Verma', accountNo: 'ACC-10089', product: 'Home Loan', risk: 'HIGH' },\n  { id: 'C004', name: 'Sneha Nair', accountNo: 'ACC-10112', product: 'Auto Loan', risk: 'LOW' },\n  { id: 'C005', name: 'Vikram Singh', accountNo: 'ACC-10134', product: 'Business Loan', risk: 'HIGH' },\n  { id: 'C006', name: 'Deepa Kumar', accountNo: 'ACC-10156', product: 'Credit Card', risk: 'LOW' },\n  { id: 'C007', name: 'Aditya Rao', accountNo: 'ACC-10178', product: 'Personal Loan', risk: 'MEDIUM' },\n  { id: 'C008', name: 'Kavya Reddy', accountNo: 'ACC-10200', product: 'Home Loan', risk: 'LOW' },\n  { id: 'C009', name: 'Manish Joshi', accountNo: 'ACC-10222', product: 'Auto Loan', risk: 'MEDIUM' },\n  { id: 'C010', name: 'Ananya Das', accountNo: 'ACC-10244', product: 'Business Loan', risk: 'HIGH' },\n];\n\n/**\n * CustomerSearchService\n *\n * Simulates a real-world customer search API endpoint.\n * Includes artificial latency of 300ms to mimic network round-trip.\n *\n * In production Fintech apps this would call:\n *   GET /api/v1/customers/search?q={query}&limit=10\n */\n@Injectable({ providedIn: 'root' })\nexport class CustomerSearchService {\n  private _totalApiCalls = 0;\n\n  get totalApiCalls(): number {\n    return this._totalApiCalls;\n  }\n\n  /**\n   * Simulated search â€” each call increments the API call counter.\n   * The `tap` operator lets us track side effects without altering the stream.\n   */\n  search(query: string): Observable<CustomerResult[]> {\n    const trimmed = query.trim().toLowerCase();\n    const results = trimmed\n      ? MOCK_CUSTOMERS.filter(\n          (c) =>\n            c.name.toLowerCase().includes(trimmed) ||\n            c.accountNo.toLowerCase().includes(trimmed) ||\n            c.product.toLowerCase().includes(trimmed)\n        )\n      : [];\n\n    return of(results).pipe(\n      tap(() => this._totalApiCalls++), // count the call\n      delay(300)                         // simulate network latency\n    );\n  }\n\n  resetCallCount(): void {\n    this._totalApiCalls = 0;\n  }\n}\n";

export const SIGNALS_VS_RXJS_TS = `import {
  Component, signal, computed, effect, OnInit, OnDestroy, untracked
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { BehaviorSubject, combineLatest, Subject, of, Observable } from 'rxjs';
import { map, takeUntil, delay, switchMap, startWith } from 'rxjs/operators';
import { rxResource } from '@angular/core/rxjs-interop';

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// RULE: computed() must be PURE (no side-effects).
// Side-effects (logging, DOM updates) belong in effect().
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export class SignalsVsRxjsComponent implements OnInit, OnDestroy {

  // â”€â”€ SIGNALS â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  priceSig    = signal<number>(100);
  quantitySig = signal<number>(2);
  discountSig = signal<number>(10);
  currencySig = signal<'USD' | 'EUR' | 'INR'>('USD');

  // Pure derivations â€” reactive graph, lazily evaluated
  subtotalSig    = computed(() => priceSig() * quantitySig());
  discountAmtSig = computed(() => (subtotalSig() * discountSig()) / 100);
  totalSig       = computed(() => subtotalSig() - discountAmtSig());

  // Angular 19: rxResource bridges async HTTP with Signals
  currencyRateResource = rxResource({
    request: () => currencySig(),           // re-fetches when currency changes
    loader: ({ request: c }) => fetchRate(c) // returns Observable<number>
  });

  convertedTotalSig = computed(() =>
    totalSig() * (currencyRateResource.value() ?? 1.0)
  );

  constructor() {
    // effect() = the correct place for side-effects in the Signals world
    // Runs once initially, then re-runs whenever any read signal changes.
    // untracked() prevents nested reads from registering extra dependencies.
    effect(() => {
      const tot = totalSig();
      untracked(() => console.log('Signals total:', tot));
    });
  }

  // â”€â”€ RxJS â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  price$    = new BehaviorSubject<number>(100);
  quantity$ = new BehaviorSubject<number>(2);
  discount$ = new BehaviorSubject<number>(10);

  subtotal$   = combineLatest([price$, quantity$]).pipe(
    map(([p, q]) => p * q)
  );
  discountAmt$ = combineLatest([subtotal$, discount$]).pipe(
    map(([s, d]) => (s * d) / 100)
  );
  total$ = combineLatest([subtotal$, discountAmt$]).pipe(
    map(([s, d]) => s - d)
  );

  // switchMap cancels in-flight requests when currency changes
  exchangeRate$ = currency$.pipe(
    switchMap(c => fetchRate(c)),
    startWith(1.0)
  );

  private destroy$ = new Subject<void>();

  ngOnInit() {
    // Must explicitly subscribe â€” RxJS is lazy until subscribed
    this.total$.pipe(takeUntil(this.destroy$)).subscribe();
  }

  // â”€â”€ THE GLITCH â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  // Two synchronous .next() calls â†’ combineLatest fires TWICE:
  //   Emission 1: newPrice Ã— OLD_qty  â† GLITCH (stale state)
  //   Emission 2: newPrice Ã— newQty   â† correct
  //
  // Signals batch both .set() calls, graph recalculates ONCE.
  triggerGlitch() {
    this.price$.next(150);    // combineLatest emits: 150 Ã— 2 â† GLITCH
    this.quantity$.next(3);   // combineLatest emits: 150 Ã— 3 â† correct

    this.priceSig.set(150);   // no emission yet
    this.quantitySig.set(3);  // computed only recalculates when READ, ONCE
  }

  ngOnDestroy() { this.destroy$.next(); this.destroy$.complete(); }
}
`;

