export const LIFECYCLE_MUTATION_TS = `// parent-triggers.ts (Mutability Trap)
/* 1. Object Mutation (ngOnChanges will NOT fire) */
mutateInPlace() {
  this.objectVal.name = 'John';
}

/* 2. Object Reassignment (ngOnChanges WILL fire) */
reassignObjectRef() {
  this.objectVal = { ...this.objectVal, name: 'John' };
}`;

export const CHANGE_DETECTION_TS = `// child-onpush.component.ts
@Component({
  selector: 'app-child-onpush',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: '<div>{{ userData.name }}</div>'
})
export class ChildOnPushComponent implements DoCheck {
  @Input() userData!: { name: string };
  @Input() strategy = 'none';

  constructor(private cdr: ChangeDetectorRef) {}

  private lastKnownName = '';

  ngDoCheck() {
    // ngDoCheck runs on EVERY Change Detection tick, even for OnPush!
    if (this.userData.name !== this.lastKnownName) {
      this.lastKnownName = this.userData.name;

      if (this.strategy === 'markForCheck') {
        this.cdr.markForCheck(); // marks path to root for dirty checking
      } else if (this.strategy === 'detectChanges') {
        this.cdr.detectChanges(); // immediately checks this component subtree
      }
    }
  }
}`;

export const ZONE_LEAKS_TS = `// zone-leaks.ts
export class ZoneLeaksComponent implements OnInit, OnDestroy {
  constructor(private ngZone: NgZone, private cdr: ChangeDetectorRef) {}

  /* 1. Run outside Angular Zone to optimize high-frequency timers */
  runOutsideZone() {
    this.ngZone.runOutsideAngular(() => {
      this.timerId = setInterval(() => {
        this.timerCount++; // updates in memory, does NOT trigger CD!
      }, 50);
    });
  }

  /* 2. Unsubscribe mitigation in ngOnDestroy */
  ngOnInit() {
    // takeUntil prevents memory leaks by completing subscription on destroy
    interval(1000)
      .pipe(takeUntil(this.destroy$))
      .subscribe(tick => console.log(tick));
  }

  ngOnDestroy() {
    this.destroy$.next();
    this.destroy$.complete();
  }
}`;


export const SIGNALS_VS_RXJS_HTML = `<!-- Signals: read directly in template, no async pipe needed -->
<div>Subtotal: {{ subtotalSig() | currency }}</div>
<div>Discount: {{ discountAmtSig() | currency }}</div>
<div>Total:    {{ totalSig()    | currency }}</div>

<!-- Async resource: loading/error states via signals -->
<div *ngIf="!currencyRateResource.isLoading(); else loading">
  Converted: {{ currencySig() }} {{ convertedTotalSig() | number:'1.2-2' }}
</div>
<ng-template #loading><span class="spinner"></span></ng-template>

<!-- RxJS: requires async pipe to unwrap Observable -->
<div>Subtotal: {{ subtotal$ | async | currency }}</div>
<div>Total:    {{ total$    | async | currency }}</div>
`;
